<?php
require __DIR__.'/bootstrap.php';

if(isset($_GET['api'])){require_login();header('Content-Type: application/json; charset=utf-8');if($_GET['api']==='products'){$q='%'.trim($_GET['q']??'').'%';$s=$pdo->prepare('SELECT id,english_name,tamil_name,unit,default_rate FROM products WHERE active=1 AND english_name LIKE ? ORDER BY english_name LIMIT 15');$s->execute([$q]);echo json_encode($s->fetchAll(),JSON_UNESCAPED_UNICODE);}exit;}
$page=$_GET['page']??(logged_in()?'dashboard':'login');
if($page==='logout'){session_destroy();redirect('?page=login');}
if($page==='login'&&$_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('SELECT * FROM users WHERE username=?');$s->execute([trim($_POST['username']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];redirect('index.php');}flash('Incorrect username or password.','error');redirect('?page=login');}
if($page!=='login'&&$page!=='public_bill')require_login();

if($_SERVER['REQUEST_METHOD']==='POST'&&$page!=='login'){
 check_csrf();$action=$_POST['action']??'';
 try{
  if($action==='save_category'){$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Category name is required.');if($id){$s=$pdo->prepare('UPDATE categories SET name=?,active=? WHERE id=?');$s->execute([$name,isset($_POST['active'])?1:0,$id]);}else{$s=$pdo->prepare('INSERT INTO categories(name) VALUES(?)');$s->execute([$name]);}flash('Category saved.');redirect('?page=categories');}
  if($action==='save_product'){$id=(int)($_POST['id']??0);$vals=[(int)$_POST['category_id']?:null,trim($_POST['english_name']),trim($_POST['tamil_name']),trim($_POST['unit']),max(0,(float)$_POST['default_rate']),isset($_POST['active'])?1:0];if($vals[1]===''||$vals[2]==='')throw new RuntimeException('English and Tamil names are required.');if($id){$vals[]=$id;$s=$pdo->prepare('UPDATE products SET category_id=?,english_name=?,tamil_name=?,unit=?,default_rate=?,active=? WHERE id=?');}else{$s=$pdo->prepare('INSERT INTO products(category_id,english_name,tamil_name,unit,default_rate,active) VALUES(?,?,?,?,?,?)');}$s->execute($vals);flash('Product saved.');redirect('?page=products');}
  if($action==='save_customer'){$id=(int)($_POST['id']??0);$vals=[trim($_POST['name']),preg_replace('/[^0-9+]/','',$_POST['mobile']??''),trim($_POST['address']??''),(float)($_POST['opening_balance']??0)];if($vals[0]==='')throw new RuntimeException('Customer name is required.');if($id){$vals[]=$id;$s=$pdo->prepare('UPDATE customers SET name=?,mobile=?,address=?,opening_balance=? WHERE id=?');}else{$s=$pdo->prepare('INSERT INTO customers(name,mobile,address,opening_balance) VALUES(?,?,?,?)');}$s->execute($vals);flash('Customer saved.');redirect('?page=customers');}
  if($action==='save_payment'){$cid=(int)$_POST['customer_id'];$amount=(float)$_POST['amount'];if($cid<1||$amount<=0)throw new RuntimeException('Select a customer and enter a valid payment.');$s=$pdo->prepare('INSERT INTO payments(customer_id,amount,note) VALUES(?,?,?)');$s->execute([$cid,$amount,trim($_POST['note']??'')]);flash('Payment recorded.');redirect('?page=customers');}
  if($action==='save_bill'){
   $billId=(int)($_POST['bill_id']??0);$cid=(int)($_POST['customer_id']??0);if($cid<1)throw new RuntimeException('Select a customer.');$items=[];$sum=0;
   $productLookup=$pdo->prepare('SELECT id,english_name,tamil_name,unit FROM products WHERE id=? AND active=1');
   foreach($_POST['english_name']??[] as $i=>$english){$row=$i+1;$english=trim($english);$productId=(int)($_POST['product_id'][$i]??0);$qty=(float)($_POST['quantity'][$i]??0);$rate=(float)($_POST['rate'][$i]??0);if($english===''&&$productId===0)continue;if($productId<1)throw new RuntimeException("Select a product from suggestions in row {$row}.");if(!is_finite($qty)||$qty<=0)throw new RuntimeException("Enter a valid quantity in row {$row}.");if(!is_finite($rate)||$rate<0)throw new RuntimeException("Enter a valid non-negative rate in row {$row}.");$productLookup->execute([$productId]);$product=$productLookup->fetch();if(!$product)throw new RuntimeException("The selected product in row {$row} is unavailable.");$amount=round($qty*$rate,2);if(!is_finite($amount)||$amount<0)throw new RuntimeException("Invalid amount in row {$row}.");$sum=round($sum+$amount,2);$items[]=[$productId,$product['english_name'],$product['tamil_name'],$qty,$product['unit'],$rate,$amount];}
   if(!$items)throw new RuntimeException('Add at least one valid product.');$received=(float)($_POST['amount_received']??0);if(!is_finite($received)||$received<0)throw new RuntimeException('Enter a valid amount received.');if($received>$sum)throw new RuntimeException('Amount received cannot exceed the bill total.');$pdo->beginTransaction();
   if($billId){$s=$pdo->prepare('UPDATE bills SET customer_id=?,subtotal=?,amount_received=? WHERE id=? AND status="active"');$s->execute([$cid,$sum,$received,$billId]);$pdo->prepare('DELETE FROM bill_items WHERE bill_id=?')->execute([$billId]);}
   else{$s=$pdo->query('SELECT setting_value FROM settings WHERE setting_key="next_bill_no" FOR UPDATE');$next=(int)($s->fetchColumn()?:1);$s=$pdo->prepare('INSERT INTO bills(bill_no,customer_id,subtotal,amount_received,share_token) VALUES(?,?,?,?,?)');$s->execute([$next,$cid,$sum,$received,bin2hex(random_bytes(32))]);$billId=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE settings SET setting_value=? WHERE setting_key="next_bill_no"')->execute([(string)($next+1)]);}
   $s=$pdo->prepare('INSERT INTO bill_items(bill_id,product_id,english_name,tamil_name,quantity,unit,rate,amount) VALUES(?,?,?,?,?,?,?,?)');foreach($items as $item)$s->execute(array_merge([$billId],$item));$pdo->commit();flash('Bill saved.');redirect('?page=view_bill&id='.$billId);
  }
  if($action==='cancel_bill'){$id=(int)$_POST['id'];$pdo->prepare('UPDATE bills SET status="cancelled" WHERE id=?')->execute([$id]);flash('Bill cancelled; customer balance updated.');redirect('?page=bills');}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');redirect($_SERVER['HTTP_REFERER']??'index.php');}
}

function header_html(string $title): void { global $page; $f=$_SESSION['flash']??null;unset($_SESSION['flash']);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b432a"><title><?=e($title)?> — SGAS</title><link rel="stylesheet" href="assets/app.css?v=20260831-1"></head><body><?php if(logged_in()):?><button type="button" class="menu-toggle no-print" aria-label="Open menu" aria-expanded="false">☰</button><nav class="no-print"><strong>SGAS</strong><a href="index.php">Dashboard</a><a href="?page=new_bill">New Bill</a><a href="?page=bills">Bills</a><a href="?page=customers">Customers</a><a href="?page=products">Products</a><a href="?page=categories">Categories</a><a href="?page=logout">Logout</a></nav><?php endif;?><main class="wrap"><?php if($f):?><div class="notice <?=$f['type']==='error'?'error':''?>"><?=e($f['msg'])?></div><?php endif;?><?php }
function footer_html(): void {?></main><script src="assets/app.js?v=20260831-1"></script></body></html><?php }

if($page==='login'){header_html('Sign in');?><div class="card login"><h1>SGAS</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><p><label>Username</label><input name="username" autocomplete="username" required autofocus></p><p><label>Password</label><input type="password" name="password" autocomplete="current-password" required></p><button>Sign in</button></form></div><?php footer_html();exit;}

if($page==='dashboard'){header_html('Dashboard');$customers=(int)$pdo->query('SELECT COUNT(*) FROM customers')->fetchColumn();$products=(int)$pdo->query('SELECT COUNT(*) FROM products WHERE active=1')->fetchColumn();$bills=(int)$pdo->query("SELECT COUNT(*) FROM bills WHERE status='active'")->fetchColumn();?><h1>Business Overview</h1><p class="muted" style="margin-top:-17px;margin-bottom:24px">Welcome back. Here is your SGAS billing summary.</p><div class="grid stats"><div class="card stat">Total Customers<b><?=$customers?></b></div><div class="card stat">Active Products<b><?=$products?></b></div><div class="card stat">Total Bills<b><?=$bills?></b></div></div><div class="card"><h2>Quick Actions</h2><div class="actions"><a class="btn" href="?page=new_bill">＋ Create New Bill</a><a class="btn secondary" href="?page=customers">Record Customer Payment</a><a class="btn secondary" href="?page=products">Add New Product</a></div></div><?php footer_html();exit;}

if($page==='categories'){$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM categories WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();header_html('Categories');?><h1>Product Categories</h1><div class="grid"><div class="card"><h2><?=$edit?'Edit':'Add'?> Category</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_category"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><p><label>Category name</label><input name="name" value="<?=e($edit['name']??'')?>" required></p><?php if($edit):?><p><label><input style="width:auto" type="checkbox" name="active" <?=$edit['active']?'checked':''?>> Active</label></p><?php endif;?><button>Save Category</button></form></div><div class="card"><h2>Categories</h2><table><tr><th>Name</th><th>Products</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=$r['product_count']?></td><td><a href="?page=categories&edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table></div></div><?php footer_html();exit;}

if($page==='products'){$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$cats=$pdo->query('SELECT * FROM categories WHERE active=1 ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.english_name')->fetchAll();header_html('Products');?><h1>Products</h1><div class="card"><h2><?=$edit?'Edit':'Add'?> Product</h2><form method="post" class="grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><p><label>Category</label><select name="category_id"><option value="0">No category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></p><p><label>English name (search)</label><input name="english_name" value="<?=e($edit['english_name']??'')?>" required></p><p><label>Tamil name (print)</label><input lang="ta" name="tamil_name" value="<?=e($edit['tamil_name']??'')?>" required></p><p><label>Unit</label><input name="unit" value="<?=e($edit['unit']??'Nos')?>" required></p><p><label>Default rate</label><input type="number" step="0.01" min="0" name="default_rate" value="<?=e($edit['default_rate']??'0')?>"></p><p><label><input style="width:auto" type="checkbox" name="active" <?=!$edit||$edit['active']?'checked':''?>> Active</label><br><button>Save Product</button></p></form></div><div class="card"><table><tr><th>English search name</th><th>Tamil print name</th><th>Category</th><th>Unit</th><th>Rate</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['english_name'])?></td><td lang="ta"><?=e($r['tamil_name'])?></td><td><?=e($r['category'])?></td><td><?=e($r['unit'])?></td><td><?=money($r['default_rate'])?></td><td><a href="?page=products&edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='customers'){$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM customers WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM customers ORDER BY name')->fetchAll();header_html('Customers');?><h1>Customers & Balances</h1><div class="grid"><div class="card"><h2><?=$edit?'Edit':'Add'?> Customer</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_customer"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><p><label>Name</label><input name="name" value="<?=e($edit['name']??'')?>" required></p><p><label>Mobile with country code</label><input name="mobile" placeholder="919677811194" value="<?=e($edit['mobile']??'')?>"></p><p><label>Address</label><textarea name="address"><?=e($edit['address']??'')?></textarea></p><p><label>Opening balance</label><input type="number" step="0.01" name="opening_balance" value="<?=e($edit['opening_balance']??'0')?>"></p><button>Save Customer</button></form></div><div class="card"><h2>Record Payment</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_payment"><p><label>Customer</label><select name="customer_id" required><option value="">Select</option><?php foreach($rows as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></p><p><label>Amount received</label><input type="number" min="0.01" step="0.01" name="amount" required></p><p><label>Note</label><input name="note"></p><button>Record Payment</button></form></div></div><div class="card"><table><tr><th>Customer</th><th>Mobile</th><th class="right">Balance</th><th>Actions</th></tr><?php foreach($rows as $r):$bal=customer_balance($pdo,(int)$r['id']);$msg=str_replace(['{name}','{balance}'],[$r['name'],money($bal)],setting($pdo,'reminder_tamil'));$phone=preg_replace('/\D/','',$r['mobile']);?><tr><td><?=e($r['name'])?></td><td><?=e($r['mobile'])?></td><td class="right">₹<?=money($bal)?></td><td class="actions"><a href="?page=customers&edit=<?=$r['id']?>">Edit</a><?php if($phone):?><a target="_blank" href="https://wa.me/<?=e($phone)?>?text=<?=rawurlencode($msg)?>">WhatsApp Reminder</a><?php endif;?></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='new_bill'||$page==='edit_bill'){$bill=null;$existing=[];if($page==='edit_bill'){$s=$pdo->prepare('SELECT * FROM bills WHERE id=? AND status="active"');$s->execute([(int)$_GET['id']]);$bill=$s->fetch();if(!$bill)exit('Bill not found.');$s=$pdo->prepare('SELECT * FROM bill_items WHERE bill_id=?');$s->execute([$bill['id']]);$existing=$s->fetchAll();}$customers=$pdo->query('SELECT * FROM customers ORDER BY name')->fetchAll();header_html($bill?'Edit Bill':'New Bill');?><div class="page-heading"><div><h1><?=$bill?'Edit Bill #'.str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT):'New Bill'?></h1><p>Fast product entry and customer billing</p></div></div><form method="post" class="card bill-form" id="bill-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_bill"><input type="hidden" name="bill_id" value="<?=e($bill['id']??'')?>"><div class="customer-panel grid"><p><label>Customer</label><select name="customer_id" required><option value="">Select customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=($bill['customer_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?><?=customer_balance($pdo,(int)$c['id'],$bill['id']??null)!=0?' — Balance ₹'.money(customer_balance($pdo,(int)$c['id'],$bill['id']??null)):''?></option><?php endforeach;?></select></p><p><label>Amount Received</label><input type="number" name="amount_received" min="0" step="0.01" value="<?=e($bill['amount_received']??'0')?>"></p></div><div class="products-heading"><div><h2>Bill Products</h2><p class="muted">Search in English · Print in Tamil</p></div><button type="button" class="btn secondary" id="add-row">＋ Add Row</button></div><div id="items"></div><div class="bill-footer"><button class="save-bill">Save Bill</button><div class="total">Grand Total <span>₹<b id="subtotal">0.00</b></span></div></div></form><template id="item-template"><div class="item-row"><div class="sno-cell"><label>S.No</label><b class="row-number">1</b></div><div class="product-cell searchbox"><label>Product (English Search)</label><input class="product-search" name="english_name[]" autocomplete="off" required><input type="hidden" class="product-id" name="product_id[]"><input type="hidden" class="tamil-name" name="tamil_name[]"><div class="suggestions"></div></div><div><label>Qty</label><input class="qty" name="quantity[]" type="number" min="0.001" step="0.001" value="1"></div><div><label>Unit</label><input class="unit" name="unit[]" readonly></div><div><label>Rate</label><input class="rate" name="rate[]" type="number" min="0" step="0.01"></div><div><label>Amount</label><input class="amount" readonly></div><button type="button" class="danger remove" aria-label="Remove row">×</button></div></template><?php if($existing):?><script>window.addEventListener('DOMContentLoaded',()=>{<?php foreach($existing as $x):?>addRow(<?=json_encode(['product_id'=>$x['product_id'],'english_name'=>$x['english_name'],'tamil_name'=>$x['tamil_name'],'unit'=>$x['unit'],'default_rate'=>$x['rate']],JSON_UNESCAPED_UNICODE)?>);let r=document.querySelector('#items .item-row:last-child');r.querySelector('.qty').value=<?=json_encode($x['quantity'])?>;recalc();<?php endforeach;?>});</script><?php endif;footer_html();exit;}

if($page==='bills'){$rows=$pdo->query('SELECT b.*,c.name customer FROM bills b JOIN customers c ON c.id=b.customer_id ORDER BY b.id DESC')->fetchAll();header_html('Bills');?><div class="actions"><h1 style="margin-right:auto">Bills</h1><a class="btn" href="?page=new_bill">New Bill</a></div><div class="card"><table><tr><th>Bill No.</th><th>Customer</th><th class="right">Total</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=str_pad($r['bill_no'],4,'0',STR_PAD_LEFT)?></td><td><?=e($r['customer'])?></td><td class="right">₹<?=money($r['subtotal'])?></td><td><?=e(ucfirst($r['status']))?></td><td class="actions"><a href="?page=view_bill&id=<?=$r['id']?>">View/Print</a><?php if($r['status']==='active'):?><a href="?page=edit_bill&id=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Cancel this bill?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="cancel_bill"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Cancel</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='view_bill'||$page==='public_bill'){$public=$page==='public_bill';if($public){$s=$pdo->prepare('SELECT b.*,c.name customer,c.mobile,c.address FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.share_token=? AND b.status="active"');$s->execute([$_GET['token']??'']);}else{$s=$pdo->prepare('SELECT b.*,c.name customer,c.mobile,c.address FROM bills b JOIN customers c ON c.id=b.customer_id WHERE b.id=?');$s->execute([(int)$_GET['id']]);}$bill=$s->fetch();if(!$bill)exit('Bill not found.');$s=$pdo->prepare('SELECT * FROM bill_items WHERE bill_id=?');$s->execute([$bill['id']]);$items=$s->fetchAll();$balance=customer_balance($pdo,(int)$bill['customer_id']);$shareUrl=$config['base_url'].'/?page=public_bill&token='.$bill['share_token'];header_html('Bill #'.$bill['bill_no']);?><div class="actions no-print"><?php if(!$public):?><a class="btn secondary" href="?page=bills">Back</a><?php if($bill['status']==='active'):?><a class="btn" href="?page=edit_bill&id=<?=$bill['id']?>">Edit</a><?php endif;?><?php endif;?><button onclick="window.print()">Print / Save PDF</button><?php if(!$public):?><button onclick="shareBill('SGAS Bill #<?=str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT)?>','<?=e($shareUrl)?>')">Share to WhatsApp</button><?php endif;?></div><div class="card bill-print"><h1>SGAS</h1><?php if($bill['status']==='cancelled'):?><div class="notice error no-print">CANCELLED</div><?php endif;?><div class="grid"><div><b>Bill No:</b> <?=str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT)?></div><div><b>Customer:</b> <?=e($bill['customer'])?><br><?=nl2br(e($bill['address']))?><br><?=e($bill['mobile'])?></div></div><br><table><thead><tr><th>S.No</th><th>பொருள்</th><th class="right">அளவு</th><th>அலகு</th><th class="right">விலை</th><th class="right">தொகை</th></tr></thead><tbody><?php foreach($items as $i=>$x):?><tr><td><?=$i+1?></td><td lang="ta"><?=e($x['tamil_name'])?></td><td class="right"><?=rtrim(rtrim(number_format($x['quantity'],3),'0'),'.')?></td><td><?=e($x['unit'])?></td><td class="right"><?=money($x['rate'])?></td><td class="right"><?=money($x['amount'])?></td></tr><?php endforeach;?></tbody></table><table class="summary"><tr><td>மொத்தம்</td><td class="right">₹<?=money($bill['subtotal'])?></td></tr><?php if((float)$bill['amount_received']>0):?><tr><td>பெற்ற தொகை</td><td class="right">₹<?=money($bill['amount_received'])?></td></tr><?php endif;?><tr><td><b>வாடிக்கையாளர் நிலுவை</b></td><td class="right"><b>₹<?=money($balance)?></b></td></tr></table></div><?php footer_html();exit;}

http_response_code(404);header_html('Not found');?><div class="card"><h1>Page not found</h1></div><?php footer_html();
